    rclcpp::Client<std_srvs::srv::Empty>::SharedPtr client_reset;    
    rclcpp::Service<std_srvs::srv::Trigger>::SharedPtr srv_update_global_map;
    std::mutex m_map_update;

    PoseVisualization lc_vis;
